ent_name}: ${r.current.ok ? 'right page' : 'wrong page'}. Conare: ${r.conare.ok ? 'right page' : 'wrong page'}.`}</span></button>`)}${this.shown < list.length ? html`${staticHtml`<${tag('button')} variant="ghost" press class="mt-2 self-start" @click=${() => { this.shown += 12 }}>Show 12 more</${tag('button')}>`}` : nothing}</div><section class="ds-testpanel m-1.25" aria-label="the question on show">${staticHtml`<${tag('grain')}></${tag('grain')}>`}<div class="pointer-events-none absolute inset-0 opacity-70" aria-hidden="true">${staticHtml`<${tag('cell-burst')} seed="31" jumble></${tag('cell-burst')}>`}</div><div class="relative w-full border border-code-edge bg-code text-code-fg"><div class="flex h-11 items-center gap-2 px-4 text-ui leading-4"><span class="size-2 shrink-0 bg-surface-accent" aria-hidden="true"></span><span class="truncate">Your test</span><span class="shrink-0 bg-code-raised px-1.5 py-0.5 type-meta tabular-nums">${running ? `${view.done} of ${view.questions}` : `${view.questions} questions`}</span></div><div class="ds-testfield" role="img" aria-label=${`${view.right} of ${view.questions} questions reached the right page`} @pointermove=${this.pointField} @click=${this.clickField}>${cells.map((c, i) => html`<span class="ds-testcell" data-id=${c.id} ?data-ok=${c.ok} ?data-queued=${c.queued} ?data-dim=${!c.queued && !inList.has(c.id)} style="--r: ${Math.floor(i / COLS)}"></span>`)}${picked ? html`<span class="ds-testline" data-h aria-hidden="true" style=${`transform: translateY(calc(${pitch(scope.r)} + ${half}))`}></span><span class="ds-testline" data-v aria-hidden="true" style=${`transform: translateX(calc(${pitch(scope.c)} + ${half}))`}></span><svg class="ds-bracket" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true" style=${`transform: translate(${pitch(scope.c)}, ${pitch(scope.r)})`}><path d="M0 34V0H34M66 0H100V34M100 66V100H66M34 100H0V66" vector-effect="non-scaling-stroke"></path></svg>` : nothing}</div><div class="grid min-h-85 border-t border-code-edge max-lg:min-h-0">${repeat(this.swaps, (s) => s.key, (s) => this.renderSwap(s))}</div></div></section></div>`
	}
