import '@/elements/components/ui/button'
import styles from 'virtual:tw'

// AccuracyDetail.vue as <conare-accuracy-detail>: One question of an accuracy test, opened (accuracy/Detail.vue): what came back, its page drawn small, the document in
// mono and the page number, the words with the part that answers in ink, and whether it reached the right page; the
// right one carries a 2px red line on top. `both` sets the team's current search and Conare side by side. Its foot says
// what to fix with the fix as a button, then Search it and Remove question: the app listens for `fix`, `search` and `remove` ({{ row }}).
export interface AccuracyHit { id: string, number: number, count: number, top: number, text: string, key: string, ok: boolean }
export interface AccuracyRow { id: string, question: string, namespace: string, conare: AccuracyHit, current: AccuracyHit, fix?: { why: string, action: string } }
export interface AccuracyView {
	state: 'running' | 'done'
	/** When it ran, as the page says it ("3 hours ago"), who ran it, how long it took and what it cost. */
	ran: string
	by: string
	seconds: number
	cost: number
	questions: number
	done: number
	right: number
	current_right: number
	current_name: string
	rows: AccuracyRow[]
	queued: Array<{ id: string, question: string, namespace: string }>
}

const split = (h: AccuracyHit) => {
	const at = h.text.indexOf(h.key)
	return at < 0 ? [h.text, '', ''] : [h.text.slice(0, at), h.key, h.text.slice(at + h.key.length)]
}

/**
 * @summary One question of an accuracy test, opened: what came back and whether it was the right page.
 * @fires fix - The fix was pressed ({ row }).
 * @fires search - Search it was pressed ({ row }).
 * @fires remove - Remove question was pressed ({ row }).
 */
export class AccuracyDetail extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { row: { type: Object }, both: { type: Boolean }, name: {} }

	row?: AccuracyRow
	/** The team's current search and Conare side by side. */
	both = false
	/** The current search's name. */
	name?: string

	render() {
		const row = this.row
		if (!row) return nothing
		const answers = this.both ? [{ label: this.name ?? 'Your current search', hit: row.current }, { label: 'Conare', hit: row.conare }] : [{ label: 'What came back', hit: row.conare }]
		const b = tag('button')
		return html`<div data-ds="accuracy-detail" class="flex flex-col bg-surface-subtle"><div class=${this.both ? 'grid md:grid-cols-2' : 'grid'}>${answers.map((a, i) => html`<div class=${i > 0 ? 'ds-answer border-edge max-md:border-t md:border-l' : 'ds-answer'} ?data-won=${a.hit.ok}><p class="type-ui-strong">${a.label}</p><div class="flex items-center gap-3">${staticHtml`<${tag('accuracy-thumb')} .number=${a.hit.number} .top=${a.hit.top}></${tag('accuracy-thumb')}>`}<p class="min-w-0"><span class="block truncate type-code-sm">${a.hit.id}</span><span class="block type-meta text-fg-muted">${`Page ${a.hit.number} of ${a.hit.count}`}</span></p></div><p class="text-body leading-5.5 text-pretty text-fg-muted">${split(a.hit)[0]}<span class="font-medium text-fg">${split(a.hit)[1]}</span>${split(a.hit)[2]}</p><span class="ds-verdict" ?data-ok=${a.hit.ok}>${a.hit.ok ? icon(Check, 'check', { size: 12, strokeWidth: 2, attrs: { 'aria-hidden': 'true' } }) : icon(X, 'x', { size: 12, strokeWidth: 2, attrs: { 'aria-hidden': 'true' } })}${a.hit.ok ? 'Right page' : 'Wrong page'}</span></div>`)}</div><div class="flex flex-wrap items-center justify-end gap-2 px-4 pb-3">${row.fix ? html`<p class="min-w-0 flex-1 max-sm:basis-full">${row.fix.why}</p>${staticHtml`<${b} press @click=${() => this.emit('fix', { row })}>${row.fix.action}</${b}>`}` : nothing}${staticHtml`<${b} variant="ghost" press @click=${() => this.emit('search', { row })}>${icon(Search, 'search', { size: 12, strokeWidth: 1.5, attrs: { 'aria-hidden': 'true' } })}Search it</${b}><${b} variant="ghost" press @click=${() => this.emit('remove', { row })}>Remove question</${b}>`}</div></div>`
	}
}

define('accuracy-detail', AccuracyDetail)

/* AccuracyDetail.vue's <style>, as it is. */
.ds-answer { position: relative; display: flex; min-width: 0; flex-direction: column; align-items: flex-start; gap: var(--ds-space-lg); padding: 16px; }
.ds-answer[data-won]::before { position: absolute; inset: 0 0 auto; height: 2px; background: var(--ds-color-edge-accent); content: ""; }
/* A result's state (.v2-proc): 12px, its icon first; a miss in the darker red. */
.ds-verdict { display: inline-flex; width: fit-content; align-items: center; gap: var(--ds-space-sm); color: var(--ds-color-fg-danger); font-size: var(--ds-text-meta); line-height: var(--ds-text-meta-leading); }
.ds-verdict[data-ok] { color: var(--ds-color-fg); }
.ds-verdict svg { flex-shrink: 0; }
td > .ds-verdict { font-size: var(--ds-text-ui); }
/* The chevron turns on a transition, so a quick second click reverses it from where it is (.v2-chev). */
.ds-chev { transition: rotate var(--ds-duration-micro) var(--ds-easing-out), color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-chev[data-open] { rotate: 180deg; transition-duration: var(--ds-duration-slide), var(--ds-duration-micro); }
.ds-table tbody tr.ds-row-open td { background: var(--ds-color-surface-subtle); }
@media (prefers-reduced-motion: reduce) { .ds-chev { transition: none; } }

import { html, nothing } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// AccuracyThumb.vue as <conare-accuracy-thumb>: A document's page drawn small (the console's SearchPagePreview at thumb size): 28 by 36, a running head, eleven
// rules, and the passage where it sits as a band of darker rules on the red tint with a 2px red edge. A picture: the
// text beside it says the page number.
const WIDTHS = [100, 97, 99, 94, 100, 62, 0, 98, 100, 95, 100, 71, 0]
const COUNT = 11

/**
 * @summary A document's page drawn small, its passage marked.
 */
export class AccuracyThumb extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { number: { type: Number }, top: { type: Number } }

	/** The page number (it picks the rules' widths). */
	number = 1
	/** Where the passage sits, 0 to 1 down the page. */
	top = 0

	render() {
		const at = Math.min(COUNT - 3, Math.round(this.top * COUNT))
		const lines = Array.from({ length: COUNT }, (_, i) => ({ w: WIDTHS[(i + this.number * 3) % WIDTHS.length]!, hit: i >= at && i < at + 2, first: i === at }))
		return html`<span data-ds="accuracy-thumb" class="ds-thumb" aria-hidden="true"><span class="ds-thumb-head"></span>${lines.map((l) => (l.first ? html`<span class="ds-thumb-hit"><span class="ds-thumb-line w-full"></span><span class="ds-thumb-line w-[68%]"></span></span>` : !l.hit ? html`<span class="ds-thumb-line" style="width: ${l.w}%" ?data-gap=${l.w === 0}></span>` : nothing))}</span>`
	}
}

define('accuracy-thumb', AccuracyThumb)

/* AccuracyThumb.vue's <style>, as it is. */
.ds-thumb { position: relative; display: flex; width: 28px; height: 36px; flex-shrink: 0; flex-direction: column; gap: var(--ds-space-2xs); overflow: hidden; padding: 4px; border: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface); }
.ds-thumb-line { display: block; height: 1px; flex-shrink: 0; background: var(--ds-color-edge-strong); opacity: 0.55; }
.ds-thumb-line[data-gap] { opacity: 0; }
.ds-thumb-head { display: block; width: 34%; height: 1px; flex-shrink: 0; margin-bottom: 1px; background: var(--ds-color-edge-strong); }
.ds-thumb-hit { display: flex; flex-shrink: 0; flex-direction: column; gap: var(--ds-space-2xs); margin: 0 -2px; padding: 1px 2px; background: linear-gradient(var(--ds-color-edge-accent), var(--ds-color-edge-accent)) left / 2px 100% no-repeat, color-mix(in srgb, var(--ds-color-edge-accent) 14%, transparent); }
.ds-thumb-hit .ds-thumb-line { background: var(--ds-color-off-black); opacity: 0.8; }

import { html, nothing, type PropertyValues } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import { enter, leave } from '@/elements/lib/transition'
import styles from 'virtual:tw'

// AccuracyOpens.vue as <conare-accuracy-opens>: A panel opening in place under its row (the console's RowOpen and Opens): the height grows from 0fr to 1fr on the
// strong ease-out, 180ms both ways as a table row, 200ms in and 140ms out as a list's; what is inside settles 4px as it
// fades in and only fades as it leaves, so nothing pops. Transitions, so a second click turns it around. Vue's table form (`colspan`)
// cannot be an element (a table holds only rows): the accuracy views draw that row themselves, as this element draws
// its list form. `rootName` is the data-ds its root says (accuracy-panel's, as Vue's fallthrough does).

/**
 * @summary A panel opening in place under its row.
 * @slot - What opens.
 */
export class AccuracyOpens extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { open: { type: Boolean }, rootName: { attribute: false }, shown: { state: true } }

	open = false
	/** The root's data-ds. */
	rootName = 'accuracy-opens'
	// In the page from the moment it opens until its leave has ended.
	private shown = false

	protected willUpdate(changed: PropertyValues) {
		super.willUpdate(changed)
		if (changed.has('open') && this.open) this.shown = true
	}

	protected updated(changed: PropertyValues) {
		super.updated(changed)
		if (!changed.has('open') || changed.get('open') === undefined) return
		const box = this.renderRoot.querySelector<HTMLElement>('.ds-opens-list')
		if (!box) return
		if (this.open) void enter(box, 'ds-opens', { enter: 200, leave: 140 })
		else void leave(box, 'ds-opens', { enter: 200, leave: 140 }).then(() => { if (!this.open) this.shown = false })
	}

	render() {
		if (!this.shown) return nothing
		return html`<div data-ds="${this.rootName}" class="ds-opens-list"><div class="ds-opens-grow"><div><slot></slot></div></div></div>`
	}
}

define('accuracy-opens', AccuracyOpens)

/* AccuracyOpens.vue's <style>, as it is. */
.ds-opens-row > td { height: 0; max-width: 0; padding: 0 !important; background: var(--ds-color-surface-subtle); white-space: normal; }
.ds-opens-grow { display: grid; grid-template-rows: 1fr; }
.ds-opens-grow > div { min-height: 0; }
:is(.ds-opens-enter-from, .ds-opens-leave-to) .ds-opens-grow { grid-template-rows: 0fr; }
:is(.ds-opens-enter-active, .ds-opens-leave-active) .ds-opens-grow { transition: grid-template-rows var(--ds-duration-slide) var(--ds-easing-out); }
.ds-opens-list:is(.ds-opens-enter-active) .ds-opens-grow { transition-duration: var(--ds-duration-enter); }
.ds-opens-list:is(.ds-opens-leave-active) .ds-opens-grow { transition-duration: var(--ds-duration-fade); }
:is(.ds-opens-enter-active, .ds-opens-leave-active) .ds-opens-grow > div { overflow: hidden; }
.ds-opens-enter-active .ds-opens-grow > div { transition: opacity var(--ds-duration-micro) var(--ds-easing-out), transform var(--ds-duration-slide) var(--ds-easing-out); }
.ds-opens-leave-active .ds-opens-grow > div { transition: opacity var(--ds-duration-cell) var(--ds-easing-out); }
.ds-opens-enter-from .ds-opens-grow > div { opacity: 0; transform: translateY(-4px); }
.ds-opens-leave-to .ds-opens-grow > div { opacity: 0; }
@media (prefers-reduced-motion: reduce) {
  :is(.ds-opens-enter-active, .ds-opens-leave-active) :is(.ds-opens-grow, .ds-opens-grow > div) { transition: none; }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit'

/**
 * useGlideMark as a Lit controller: one block for a whole list (the website's Product menu highlight): it glides on
 * transform to the row under the pointer or focus, and rests on the current row (`rest`) when the pointer leaves, or
 * hides when there is none. Rows are the list's [data-glide-row] elements, in order, each positioned relative to the
 * list. The first placement doesn't glide. It settles once the host has first rendered. Draw the block with
 * <conare-glide-mark>, which uses this on its own list when it has `follow`.
 */
export class GlideMarkController implements ReactiveController {
	mark: { y: number, h: number } | null = null
	shown = false
	instant = true
	hot: number | null = null

	constructor(private host: ReactiveControllerHost, private list: () => HTMLElement | null | undefined, private rest: () => number | null) {
		host.addController(this)
	}

	hostConnected() {
		void this.host.updateComplete.then(() => this.settle())
	}

	private place(i: number | null, instantly: boolean) {
		const row = i === null ? undefined : this.list()?.querySelectorAll<HTMLElement>('[data-glide-row]')[i]
		if (!row) {
			this.shown = false
			this.hot = null
			this.host.requestUpdate()
			return
		}
		this.instant = instantly
		this.mark = { y: row.offsetTop, h: row.offsetHeight }
		this.shown = true
		this.hot = i
		this.host.requestUpdate()
	}

	/** The pointer or focus is on row `i`. */
	point = (i: number) => this.place(i, !this.shown)
	/** The pointer left the list: back to the resting row, gliding. */
	leave = () => this.place(this.rest(), false)
	/** The resting row changed: put the block there at once. */
	settle = () => this.place(this.rest(), true)
}
